mapper.select:
select * from ww_ds t where 1=1

	and product = #{product}


	and (product = #{nullAndProduct} or product is null)


	and agent = #{agent}


	and (agent = #{nullAndAgent} or agent is null)


	and instr(agent,#{lAgent}) > 0


	and name = #{name}


	and instr(name,#{lName}) > 0


and exists (
  select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr 
    where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id 
      and (tp.p_id=t.product or t.product is null) and tsu.login_name=#{loginName}
)

